const tupleToEntry = (t: CompactLogTuple): ClubAuditLogEntry => {
  const [event, dateDisplay, dateYmd, ip, responsible] = t;
  const br = /^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})$/.exec(dateDisplay);
  const dateIso = br
    ? new Date(`${br[3]}-${br[2]}-${br[1]}T${br[4]}:${br[5]}:${br[6]}-04:00`).toISOString()
    : `${dateYmd}T12:00:00.000Z`;
  return {
    event,
    dateDisplay,
    dateIso,
    ip: ip || undefined,
    responsible: responsible || undefined,
    source: 'LABCARD_LOG',
  };
};

export const getLabcardAuditEvidenceByCard = (
  subscriptionCode?: string | null
): { acceptanceLog?: ClubAuditLogEntry; auditLogs?: ClubAuditLogEntry[]; startDate?: string } => {
  const digits = String(subscriptionCode || '').replace(/\D/g, '');
  if (!digits) return {};
  const found = LABCARD_AUDIT_LOGS_RAW[digits];
  if (!found) return {};
  const [primary, milestones] = found;
  return {
    acceptanceLog: tupleToEntry(primary),
    auditLogs: milestones.map(tupleToEntry),
    startDate: primary[2],
  };
};
